{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= n <= 100000",
      "description": "The length of the mask m is between 1 and 100,000."
    },
    {
      "id": "P2",
      "expression": "len(m) == n",
      "description": "The length of the mask m is exactly n."
    },
    {
      "id": "P3",
      "expression": "all(c in ['#', '_'] for c in m)",
      "description": "The mask m consists only of the characters '#' and '_'."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "output == -1 or (1 <= output[0] <= n)",
      "description": "If there is no profile with the mask m, output -1. Otherwise, output the number of integers in the profile p' and the integers themselves."
    },
    {
      "id": "Q2",
      "expression": "output == -1 or (all(0 < p[i] <= n for i in range(output[0])))",
      "description": "If there is a profile with the mask m, the integers in the profile p' are positive and do not exceed n."
    },
    {
      "id": "Q3",
      "expression": "output == -1 or (all(m[sum(p[:i+1])-p[i]:sum(p[:i+1])] == '#'*p[i] for i in range(output[0])))",
      "description": "If there is a profile with the mask m, the profile p' satisfies the mask m."
    }
  ],
  "invariants": []
}
